'use client';

import { useEffect, useMemo, useState } from 'react';
import AppShell from '@/components/Navbar';
import { api } from '@/lib/api';

type DayOfWeek = 'Monday' | 'Tuesday' | 'Wednesday' | 'Thursday' | 'Friday' | 'Saturday';
type ViewMode = 'list' | 'week';
type FilterDay = 'All' | DayOfWeek;

interface StudentScheduleApiRow {
  schedule_id: number;
  room_number: string | null;
  building: string | null;
  room_type: string | null;
  course_code: string | null;
  course_title: string | null;
  section_name: string;
  semester: string;
  year_level: number;
  instructor_full_name: string | null;
  dept_name: string | null;
  day_of_week: string;
  time_start: string;
  time_end: string;
  is_active: boolean;
  confirmed_at: string;
}

interface ApiEnvelope<T> {
  success: boolean;
  message: string;
  data: T;
}

interface ScheduleRow {
  scheduleId: number;
  sectionName: string;
  semester: string;
  yearLevel: number;
  dayOfWeek: DayOfWeek;
  timeStart: string;
  timeEnd: string;
  courseCode: string;
  courseTitle: string;
  units: number;
  roomNumber: string;
  building: string;
  instructorName: string;
  instructorDept: string;
  confirmedAt: string;
  isActive: boolean;
}

const DAY_ORDER: DayOfWeek[] = ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];
const DAY_SHORT: Record<DayOfWeek, string> = {
  Monday: 'Mon',
  Tuesday: 'Tue',
  Wednesday: 'Wed',
  Thursday: 'Thu',
  Friday: 'Fri',
  Saturday: 'Sat',
};

function normalizeDay(day: string): DayOfWeek | null {
  const value = day.trim().toLowerCase();
  const map: Record<string, DayOfWeek> = {
    monday: 'Monday',
    tuesday: 'Tuesday',
    wednesday: 'Wednesday',
    thursday: 'Thursday',
    friday: 'Friday',
    saturday: 'Saturday',
  };
  return map[value] ?? null;
}

function fmt12(t: string) {
  const [h, m] = t.split(':').map(Number);
  const ampm = h >= 12 ? 'PM' : 'AM';
  const h12 = h % 12 || 12;
  return `${h12}:${String(m).padStart(2, '0')} ${ampm}`;
}

function toMinutes(t: string) {
  const [h, m] = t.split(':').map(Number);
  return h * 60 + m;
}

function mapRow(r: StudentScheduleApiRow): ScheduleRow | null {
  const day = normalizeDay(r.day_of_week);
  if (!day) return null;

  return {
    scheduleId: r.schedule_id,
    sectionName: r.section_name ?? 'N/A',
    semester: r.semester ?? 'N/A',
    yearLevel: r.year_level ?? 0,
    dayOfWeek: day,
    timeStart: r.time_start,
    timeEnd: r.time_end,
    courseCode: r.course_code ?? 'TBA',
    courseTitle: r.course_title ?? 'Untitled Subject',
    units: 0,
    roomNumber: r.room_number ?? 'TBA',
    building: r.building ?? 'TBA',
    instructorName: r.instructor_full_name ?? 'TBA',
    instructorDept: r.dept_name ?? 'N/A',
    confirmedAt: r.confirmed_at,
    isActive: !!r.is_active,
  };
}

function groupByCourse(rows: ScheduleRow[]) {
  const map = new Map<string, { rows: ScheduleRow[]; days: DayOfWeek[] }>();
  rows.forEach((r) => {
    const key = `${r.courseCode}-${r.sectionName}-${r.timeStart}-${r.timeEnd}`;
    if (!map.has(key)) map.set(key, { rows: [], days: [] });
    const g = map.get(key)!;
    g.rows.push(r);
    if (!g.days.includes(r.dayOfWeek)) g.days.push(r.dayOfWeek);
  });

  return Array.from(map.values()).map((g) => ({
    ...g.rows[0],
    days: g.days.sort((a, b) => DAY_ORDER.indexOf(a) - DAY_ORDER.indexOf(b)),
  }));
}

const Ico = ({ d, d2, size = 15 }: { d: string; d2?: string; size?: number }) => (
  <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.85" strokeLinecap="round" strokeLinejoin="round">
    <path d={d} />
    {d2 && <path d={d2} />}
  </svg>
);
const IcoClock = () => <Ico d="M12 2a10 10 0 100 20A10 10 0 0012 2zM12 6v6l4 2" />;
const IcoRoom = () => <Ico d="M3 9.5L12 3l9 6.5V20a1 1 0 01-1 1H4a1 1 0 01-1-1V9.5z" d2="M9 21V12h6v9" />;
const IcoUser = () => <Ico d="M20 21v-2a4 4 0 00-4-4H8a4 4 0 00-4 4v2" d2="M12 11a4 4 0 100-8 4 4 0 000 8z" />;
const IcoBook = () => <Ico d="M4 19.5A2.5 2.5 0 016.5 17H20M4 19.5A2.5 2.5 0 014 17V4h16v13M4 19.5V21" />;
const IcoGrid = () => <Ico d="M3 3h7v7H3zM14 3h7v7h-7zM14 14h7v7h-7zM3 14h7v7H3z" />;
const IcoList = () => <Ico d="M8 6h13M8 12h13M8 18h13M3 6h.01M3 12h.01M3 18h.01" />;
const IcoFilter = () => <Ico d="M22 3H2l8 9.46V19l4 2V12.46L22 3z" />;
const IcoPrint = () => <Ico d="M6 9V2h12v7M6 18H4a2 2 0 01-2-2v-5a2 2 0 012-2h16a2 2 0 012 2v5a2 2 0 01-2 2h-2" d2="M6 14h12v8H6z" />;
const IcoAlert = () => <Ico d="M12 2a10 10 0 100 20A10 10 0 0012 2zM12 8v4M12 16h.01" />;

const PALETTES = [
  { bg: '#e8f5ee', border: '#22a050', text: '#1a7a3c' },
  { bg: '#eef2ff', border: '#6366f1', text: '#3730a3' },
  { bg: '#fff8e6', border: '#f0a500', text: '#92620a' },
  { bg: '#fdecea', border: '#ef4444', text: '#991b1b' },
  { bg: '#f0f9ff', border: '#0ea5e9', text: '#0369a1' },
];

function palette(courseCode: string) {
  let h = 0;
  for (let i = 0; i < courseCode.length; i++) h = (h * 31 + courseCode.charCodeAt(i)) % 999983;
  return PALETTES[h % PALETTES.length];
}

function SubjectCard({ row }: { row: ReturnType<typeof groupByCourse>[number] }) {
  const p = palette(row.courseCode);
  return (
    <div className="card overflow-hidden">
      <div className="h-1" style={{ background: p.border }} />
      <div className="p-4">
        <div className="flex items-start justify-between gap-2 mb-3">
          <div>
            <span className="text-[11px] font-bold px-2 py-0.5 rounded-md" style={{ background: p.bg, color: p.text }}>
              {row.courseCode}
            </span>
            <h3 className="text-[13.5px] font-semibold leading-snug mt-1" style={{ color: 'var(--color-text)' }}>
              {row.courseTitle}
            </h3>
          </div>
          <span className="text-[12px] font-bold shrink-0 px-2.5 py-1 rounded-lg" style={{ background: p.bg, color: p.text }}>
            {row.units.toFixed(1)}u
          </span>
        </div>
        <div className="grid grid-cols-1 sm:grid-cols-2 gap-x-4 gap-y-1.5">
          <div className="flex items-center gap-1.5 text-[12px]" style={{ color: 'var(--color-text-secondary)' }}><IcoUser />{row.instructorName}</div>
          <div className="flex items-center gap-1.5 text-[12px]" style={{ color: 'var(--color-text-secondary)' }}><IcoRoom />{row.roomNumber} · {row.building}</div>
          <div className="flex items-center gap-1.5 text-[12px]" style={{ color: 'var(--color-text-secondary)' }}><IcoClock />{fmt12(row.timeStart)} - {fmt12(row.timeEnd)}</div>
          <div className="flex items-center gap-1.5 text-[12px]" style={{ color: 'var(--color-text-secondary)' }}><IcoBook />{row.sectionName}</div>
        </div>
        <div className="flex gap-1.5 mt-3 flex-wrap">
          {row.days.map((day) => (
            <span key={day} className="text-[10.5px] font-semibold px-2 py-0.5 rounded-full" style={{ background: p.bg, color: p.text }}>
              {DAY_SHORT[day]}
            </span>
          ))}
        </div>
      </div>
    </div>
  );
}

function WeekGrid({ rows }: { rows: ScheduleRow[] }) {
  const START_HOUR = 7;
  const END_HOUR = 19;
  const TOTAL_MINS = (END_HOUR - START_HOUR) * 60;
  const GRID_H = 640;

  const hours: string[] = [];
  for (let h = START_HOUR; h <= END_HOUR; h++) hours.push(`${h}:00`);

  const daySlots: Record<DayOfWeek, ScheduleRow[]> = {
    Monday: [],
    Tuesday: [],
    Wednesday: [],
    Thursday: [],
    Friday: [],
    Saturday: [],
  };
  rows.forEach((r) => daySlots[r.dayOfWeek].push(r));

  function top(t: string) { return ((toMinutes(t) - START_HOUR * 60) / TOTAL_MINS) * GRID_H; }
  function height(s: string, e: string) { return ((toMinutes(e) - toMinutes(s)) / TOTAL_MINS) * GRID_H; }

  return (
    <div className="overflow-x-auto">
      <div style={{ minWidth: '640px' }}>
        <div className="flex border-b" style={{ borderColor: 'var(--color-border)', height: 40 }}>
          <div style={{ width: '56px', flexShrink: 0 }} />
          {DAY_ORDER.map((day) => (
            <div key={day} className="flex-1 flex items-center justify-center" style={{ borderLeft: '1px solid var(--color-border)' }}>
              <span className="text-[12px] font-semibold" style={{ color: 'var(--color-text-secondary)' }}>{DAY_SHORT[day]}</span>
            </div>
          ))}
        </div>
        <div className="relative flex" style={{ height: GRID_H }}>
          <div style={{ width: '56px', flexShrink: 0, position: 'relative' }}>
            {hours.map((h, i) => (
              <div key={h} className="absolute right-2 text-[10px]" style={{ top: `${(i / (hours.length - 1)) * 100}%`, transform: 'translateY(-50%)', color: 'var(--color-text-muted)' }}>
                {fmt12(h)}
              </div>
            ))}
          </div>
          {DAY_ORDER.map((day) => (
            <div key={day} className="flex-1 relative" style={{ borderLeft: '1px solid var(--color-border)' }}>
              {hours.map((h, i) => (
                <div key={h} className="absolute w-full" style={{ top: `${(i / (hours.length - 1)) * 100}%`, borderTop: '1px dashed var(--color-border)', opacity: 0.6 }} />
              ))}
              {daySlots[day].map((r) => {
                const p = palette(r.courseCode);
                return (
                  <div key={r.scheduleId} className="absolute left-1 right-1 rounded-lg px-2 py-1.5 overflow-hidden" style={{ top: top(r.timeStart), height: height(r.timeStart, r.timeEnd), background: p.bg, borderLeft: `3px solid ${p.border}` }}>
                    <p className="font-bold leading-tight truncate text-[10.5px]" style={{ color: p.text }}>{r.courseCode}</p>
                    <p className="truncate leading-tight text-[9.5px]" style={{ color: p.text }}>{r.roomNumber}</p>
                  </div>
                );
              })}
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

export default function StudentSchedulePage() {
  const [view, setView] = useState<ViewMode>('list');
  const [filterDay, setFilterDay] = useState<FilterDay>('All');
  const [search, setSearch] = useState('');
  const [rows, setRows] = useState<ScheduleRow[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');

  useEffect(() => {
    let active = true;
    async function load() {
      setLoading(true);
      setError('');
      try {
        const res = await api.get<ApiEnvelope<StudentScheduleApiRow[]>>('/student/schedule');
        const mapped = (res.data ?? []).map(mapRow).filter((r): r is ScheduleRow => r !== null);
        if (active) setRows(mapped);
      } catch (e: unknown) {
        if (active) setError(e instanceof Error ? e.message : 'Failed to load schedule.');
      } finally {
        if (active) setLoading(false);
      }
    }
    load();
    return () => { active = false; };
  }, []);

  const classDays = useMemo(() => DAY_ORDER.filter((d) => rows.some((r) => r.dayOfWeek === d)), [rows]);
  const grouped = useMemo(() => groupByCourse(rows), [rows]);
  const filteredGrouped = useMemo(() => {
    const q = search.trim().toLowerCase();
    return grouped.filter((r) => (filterDay === 'All' || r.days.includes(filterDay)) && (!q || r.courseCode.toLowerCase().includes(q) || r.courseTitle.toLowerCase().includes(q) || r.instructorName.toLowerCase().includes(q) || r.roomNumber.toLowerCase().includes(q)));
  }, [grouped, filterDay, search]);
  const filteredRawRows = useMemo(() => {
    const q = search.trim().toLowerCase();
    return rows.filter((r) => (filterDay === 'All' || r.dayOfWeek === filterDay) && (!q || r.courseCode.toLowerCase().includes(q) || r.courseTitle.toLowerCase().includes(q) || r.instructorName.toLowerCase().includes(q) || r.roomNumber.toLowerCase().includes(q)));
  }, [rows, filterDay, search]);

  const semesterLabel = rows[0]?.semester ?? 'Current Semester';

  return (
    <AppShell role="student" userName="Student" pageTitle="My Schedule">
      <div>
        <div className="flex items-start justify-between gap-4 mb-5 flex-wrap">
          <div>
            <h1 className="text-[20px] font-bold" style={{ color: 'var(--color-text)' }}>Class Schedule</h1>
            <p className="text-[13px] mt-0.5" style={{ color: 'var(--color-text-muted)' }}>{semesterLabel}</p>
          </div>
          <button onClick={() => window.print()} className="btn btn-ghost text-[12.5px] flex items-center gap-1.5" style={{ padding: '7px 14px' }}>
            <IcoPrint /> Print
          </button>
        </div>

        <div className="flex items-center gap-3 mb-4 flex-wrap">
          <div className="relative flex-1" style={{ minWidth: '180px', maxWidth: '280px' }}>
            <span className="absolute left-3 top-1/2 -translate-y-1/2 pointer-events-none" style={{ color: 'var(--color-text-muted)' }}><IcoFilter /></span>
            <input type="search" placeholder="Search subject, instructor..." value={search} onChange={(e) => setSearch(e.target.value)} className="w-full rounded-lg border outline-none" style={{ paddingLeft: '2.25rem', paddingRight: '0.75rem', fontSize: '13px', height: '36px', borderColor: 'var(--color-border)', background: 'var(--color-surface)', color: 'var(--color-text)' }} />
          </div>

          <div className="flex gap-1.5 flex-wrap">
            {(['All', ...classDays] as FilterDay[]).map((d) => (
              <button key={d} onClick={() => setFilterDay(d)} className="text-[11.5px] font-semibold px-3 py-1 rounded-full" style={filterDay === d ? { background: 'var(--color-primary)', color: '#fff' } : { background: 'var(--color-surface-2)', color: 'var(--color-text-secondary)' }}>
                {d === 'All' ? 'All Days' : DAY_SHORT[d]}
              </button>
            ))}
          </div>

          <div className="flex rounded-lg p-0.5 gap-0.5 ml-auto" style={{ background: 'var(--color-surface-2)' }}>
            {([{ key: 'list', icon: <IcoList />, label: 'List' }, { key: 'week', icon: <IcoGrid />, label: 'Week' }] as const).map((v) => (
              <button key={v.key} onClick={() => setView(v.key)} className="flex items-center gap-1.5 px-3 py-1.5 rounded-md text-[12px] font-semibold" style={view === v.key ? { background: 'var(--color-surface)', color: 'var(--color-primary)', boxShadow: 'var(--shadow-xs)' } : { background: 'transparent', color: 'var(--color-text-muted)' }}>
                {v.icon} {v.label}
              </button>
            ))}
          </div>
        </div>

        {loading && (
          <div className="card p-8 text-[13px]" style={{ color: 'var(--color-text-muted)' }}>Loading schedule...</div>
        )}
        {!loading && error && (
          <div className="card p-8 flex items-center gap-2 text-[13px]" style={{ color: 'var(--color-error)' }}>
            <IcoAlert /> {error}
          </div>
        )}
        {!loading && !error && filteredRawRows.length === 0 && (
          <div className="card p-8 text-[13px]" style={{ color: 'var(--color-text-muted)' }}>No classes found for the selected filters.</div>
        )}
        {!loading && !error && filteredRawRows.length > 0 && (
          view === 'list'
            ? <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-4">{filteredGrouped.map((row, idx) => <SubjectCard key={`${row.courseCode}-${idx}`} row={row} />)}</div>
            : <div className="card p-0 overflow-hidden"><WeekGrid rows={filteredRawRows} /></div>
        )}
      </div>
    </AppShell>
  );
}
